import React, { useState } from "react";
import { motion, AnimatePresence, useReducedMotion } from "motion/react";
import { ArrowRight, RefreshCw } from "lucide-react";
import type { AppHandle } from "@app/kit/primitives";

type Props = { app?: AppHandle };

const COLS = [
  { name: "To do", color: "#B4B8C0", w: 0.7 },
  { name: "Doing", color: "#F2B94B", w: 0.45 },
  { name: "Done", color: "#4CC38A", w: 0.9 },
];

function Mark({ size = 28 }: { size?: number }) {
  return (
    <span style={{ width: size, height: size }} className="grid shrink-0 place-items-center rounded-[9px] bg-primary shadow-[0_6px_16px_-4px_hsl(var(--primary)/0.6)]">
      <svg width={size / 2} height={size / 2} viewBox="0 0 18 18" fill="none"><rect x="2" y="2" width="4" height="14" rx="1.4" fill="#fff" /><rect x="7" y="2" width="4" height="9" rx="1.4" fill="#fff" fillOpacity=".85" /><rect x="12" y="2" width="4" height="6" rx="1.4" fill="#fff" fillOpacity=".7" /></svg>
    </span>
  );
}

function GoogleG() {
  return (
    <svg width="18" height="18" viewBox="0 0 48 48" aria-hidden="true">
      <path fill="#EA4335" d="M24 9.5c3.5 0 6.6 1.2 9.1 3.6l6.8-6.8C35.9 2.4 30.4 0 24 0 14.6 0 6.5 5.4 2.6 13.2l7.9 6.1C12.4 13.6 17.7 9.5 24 9.5z" />
      <path fill="#4285F4" d="M46.5 24.5c0-1.6-.1-3.1-.4-4.5H24v9h12.7c-.6 3-2.3 5.5-4.8 7.2l7.5 5.8c4.4-4.1 7.1-10.1 7.1-17.5z" />
      <path fill="#FBBC05" d="M10.5 28.7c-.5-1.4-.8-3-.8-4.7s.3-3.2.8-4.7l-7.9-6.1C.9 16.4 0 20.1 0 24s.9 7.6 2.6 10.8l7.9-6.1z" />
      <path fill="#34A853" d="M24 48c6.5 0 11.9-2.1 15.9-5.8l-7.5-5.8c-2.1 1.4-4.9 2.3-8.4 2.3-6.3 0-11.6-4.1-13.5-9.8l-7.9 6.1C6.5 42.6 14.6 48 24 48z" />
    </svg>
  );
}

/* Three cards slide into three columns, then the loop resets. */
function Slides({ reduce }: { reduce: boolean }) {
  const T = 7;
  return (
    <div aria-hidden="true" className="mx-auto grid w-full max-w-[300px] grid-cols-3 gap-2.5">
      {COLS.map((col, i) => {
        const start = 0.1 + i * 0.16;
        return (
          <div key={col.name} className="flex flex-col gap-1.5">
            <div className="flex items-center gap-1 px-0.5 text-[10px] font-medium text-neutral-500">
              <span className="h-1.5 w-1.5 rounded-full" style={{ background: col.color }} />{col.name}
            </div>
            <div className="relative h-[64px] rounded-lg border border-dashed border-neutral-200 bg-neutral-50/70">
              <motion.div
                initial={reduce ? false : { opacity: 0, x: (1 - i) * 80, y: -44, rotate: (i - 1) * 8 }}
                animate={reduce ? { opacity: 1, x: 0, y: 0, rotate: 0 } : {
                  opacity: [0, 1, 1, 1, 0],
                  x: [(1 - i) * 80, 0, 0, 0, 0],
                  y: [-44, 0, 0, 0, 0],
                  rotate: [(i - 1) * 8, 0, 0, 0, 0],
                }}
                transition={reduce ? { duration: 0 } : { duration: T, times: [start * 0.6, start * 0.6 + 0.1, 0.8, 0.92, 1], repeat: Infinity, ease: "easeOut" }}
                className="absolute inset-1 rounded-md border border-neutral-200 bg-white p-1.5 shadow-[0_6px_14px_-8px_rgba(20,20,40,0.35)]"
              >
                <div className="h-1.5 rounded-full bg-neutral-200" style={{ width: col.w * 100 + "%" }} />
                <div className="mt-1.5 h-1.5 w-1/2 rounded-full bg-neutral-100" />
                <div className="mt-2 h-1 w-5 rounded-full" style={{ background: col.color }} />
              </motion.div>
            </div>
          </div>
        );
      })}
    </div>
  );
}

export default function KanboLogin({ app }: Props) {
  const reduce = !!useReducedMotion();
  const auth = app?.auth;
  const mode = auth?.mode === "signup" ? "up" : "in";
  const canSignUp = !!auth?.canSignUp;
  const providers = auth?.providers ?? [];
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");

  const submit = async () => {
    if (!app || busy) return;
    setBusy(true);
    setErr("");
    try {
      if (mode === "in") await app.auth.signIn(email.trim(), password);
      else await app.auth.signUp({ email: email.trim(), password, name: name.trim() });
    } catch (e) {
      setErr(e instanceof Error ? e.message : "Something went wrong. Try again.");
    } finally {
      setBusy(false);
    }
  };
  const provider = async (p: string) => {
    if (!app) return;
    setErr("");
    try { await app.auth.startProvider(p); } catch (e) { setErr(e instanceof Error ? e.message : "Couldn't start that sign-in. Try again."); }
  };
  const flip = () => {
    setErr("");
    auth?.setMode(mode === "in" ? "signup" : "login");
  };
  const onKey = (e: React.KeyboardEvent) => { if (e.key === "Enter") void submit(); };

  const inputCls = "mt-1.5 h-11 w-full rounded-lg border border-neutral-200 bg-white px-3.5 text-sm text-neutral-900 outline-none transition placeholder:text-neutral-400 focus:border-primary focus:ring-4 focus:ring-primary/15";

  return (
    <div className="flex min-h-[100dvh] w-full flex-col items-center justify-center bg-white px-6 py-10 text-neutral-900">
      <motion.div
        initial={reduce ? false : { opacity: 0, y: 14 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ type: "spring", stiffness: 140, damping: 20 }}
        className="w-full max-w-[340px]"
      >
        <div className="flex items-center justify-center gap-2"><Mark /><span className="text-[15px] font-semibold tracking-tight">Kanbo</span></div>
        <div className="mt-9"><Slides reduce={reduce} /></div>

        <h1 className="mt-9 text-center text-[22px] font-semibold tracking-tight">{mode === "in" ? "Sign in to Kanbo" : "Create your account"}</h1>
        <p className="mt-1 text-center text-[13px] text-neutral-500">Ship together, calmly.</p>

        <div className="mt-7 space-y-3.5">
          <AnimatePresence initial={false}>
            {mode === "up" && (
              <motion.div key="name" initial={{ opacity: 0, height: 0 }} animate={{ opacity: 1, height: "auto" }} exit={{ opacity: 0, height: 0 }} className="overflow-hidden">
                <label className="block text-xs font-medium text-neutral-500">
                  Name
                  <input className={inputCls} aria-label="Name" value={name} onChange={(e) => setName(e.target.value)} onKeyDown={onKey} placeholder="Your name" />
                </label>
              </motion.div>
            )}
          </AnimatePresence>
          <label className="block text-xs font-medium text-neutral-500">
            Email
            <input className={inputCls} type="email" aria-label="Email" autoComplete="email" value={email} onChange={(e) => setEmail(e.target.value)} onKeyDown={onKey} placeholder="you@company.com" />
          </label>
          <label className="block text-xs font-medium text-neutral-500">
            Password
            <input className={inputCls} type="password" aria-label="Password" autoComplete={mode === "in" ? "current-password" : "new-password"} value={password} onChange={(e) => setPassword(e.target.value)} onKeyDown={onKey} placeholder="••••••••" />
          </label>
        </div>

        <AnimatePresence>
          {err && (
            <motion.div role="alert" initial={{ opacity: 0, y: -4 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} className="mt-4 rounded-lg border border-red-200 bg-red-50 px-3 py-2 text-xs text-red-700">{err}</motion.div>
          )}
        </AnimatePresence>

        <motion.button
          whileTap={reduce ? undefined : { scale: 0.98 }}
          onClick={() => void submit()}
          disabled={busy}
          className="mt-5 flex h-11 w-full items-center justify-center gap-2 rounded-lg bg-primary text-sm font-semibold text-primary-foreground shadow-[0_8px_20px_-8px_hsl(var(--primary)/0.8)] disabled:opacity-70"
        >
          {busy ? <RefreshCw className="h-4 w-4 animate-spin" /> : null}
          {mode === "in" ? "Sign in" : "Create account"}
          {!busy && <ArrowRight className="h-4 w-4" />}
        </motion.button>
        <p className="mt-2.5 text-center text-[11px] text-neutral-400">
          Press <kbd className="rounded border border-neutral-200 bg-neutral-50 px-1.5 py-0.5 font-mono text-[10px] text-neutral-500">Enter</kbd> to {mode === "in" ? "sign in" : "create your account"}
        </p>

        {providers.length > 0 && (
          <div className="mt-5">
            <div className="flex items-center gap-3 text-[11px] uppercase tracking-wider text-neutral-400"><span className="h-px flex-1 bg-neutral-200" />or<span className="h-px flex-1 bg-neutral-200" /></div>
            <div className="mt-4 space-y-2">
              {providers.map((p) => (
                <motion.button
                  key={p.name}
                  whileTap={reduce ? undefined : { scale: 0.98 }}
                  onClick={() => void provider(p.name)}
                  className="flex h-11 w-full items-center justify-center gap-2.5 rounded-lg border border-neutral-200 bg-white text-sm font-medium text-neutral-800 transition hover:bg-neutral-50"
                >
                  {p.name === "google" ? <GoogleG /> : null}
                  Continue with {p.label}
                </motion.button>
              ))}
            </div>
          </div>
        )}

        {canSignUp && (
          <p className="mt-6 text-center text-xs text-neutral-500">
            {mode === "in" ? "New to Kanbo?" : "Already have an account?"}{" "}
            <button className="font-medium text-primary hover:underline" onClick={flip}>
              {mode === "in" ? "Create an account" : "Sign in instead"}
            </button>
          </p>
        )}
      </motion.div>
    </div>
  );
}

import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { motion, AnimatePresence, LayoutGroup, useDragControls, useReducedMotion } from "motion/react";
import type { PanInfo } from "motion/react";
import { Users, LayoutGrid, ListChecks, Layers, Plus, Search, X, Sparkles, MessageSquare, CalendarDays, Check, LogOut, Send, Zap, RefreshCw, AlertCircle } from "lucide-react";
import type { AppHandle } from "@app/kit/primitives";

type R = Record<string, unknown>;
type Props = { app?: AppHandle; openId?: string };

const s = (v: unknown): string => (v == null ? "" : String(v));
const n = (v: unknown): number => Number(v) || 0;
const STAGES = ["backlog", "todo", "in_progress", "review", "done"];
const ST_LABEL: Record<string, string> = { backlog: "Backlog", todo: "To do", in_progress: "In progress", review: "Review", done: "Done" };
const ST_COLOR: Record<string, string> = { backlog: "#8A8F98", todo: "#B4B8C0", in_progress: "#F2B94B", review: "#5EA2FF", done: "#4CC38A" };
const PRI: Record<string, { label: string; color: string; bars: number }> = {
  urgent: { label: "Urgent", color: "#FF6B6B", bars: 4 },
  high: { label: "High", color: "#FFA94D", bars: 3 },
  medium: { label: "Medium", color: "#FFD43B", bars: 2 },
  low: { label: "Low", color: "#8A8F98", bars: 1 },
};
const LCOL = ["#F472B6", "#60A5FA", "#34D399", "#A78BFA", "#FBBF24", "#2DD4BF", "#FB923C", "#93C5FD"];
const GRADS = [["#7C5CFF", "#B39BFF"], ["#14B8A6", "#38BDF8"], ["#EC4899", "#FB923C"], ["#3B82F6", "#818CF8"], ["#10B981", "#A3E635"], ["#F59E0B", "#EF4444"]];
const SPRING = { type: "spring" as const, stiffness: 420, damping: 34 };
const hash = (t: string): number => { let h = 0; for (let i = 0; i < t.length; i++) h = (h * 31 + t.charCodeAt(i)) >>> 0; return h; };
const msg = (e: unknown): string => {
  const m = e instanceof Error ? e.message : s(e);
  return /WIP/i.test(m) ? "WIP limit reached: this teammate already has 3 cards in progress." : m || "Something went wrong";
};

function Av({ name, size = 24 }: { name: string; size?: number }) {
  const g = GRADS[hash(name) % GRADS.length];
  const p = name.trim().split(/\s+/);
  const ini = ((p[0] || "?")[0] + (p.length > 1 ? p[p.length - 1][0] : "")).toUpperCase();
  return (
    <span title={name} style={{ width: size, height: size, fontSize: Math.max(8, size * 0.38), background: `linear-gradient(135deg, ${g[0]}, ${g[1]})` }} className="inline-grid shrink-0 place-items-center rounded-full font-semibold text-white ring-2 ring-card">{ini}</span>
  );
}
function StageIcon({ st, size = 14 }: { st: string; size?: number }) {
  const c = ST_COLOR[st] || "#8A8F98";
  return (
    <svg width={size} height={size} viewBox="0 0 14 14" fill="none">
      <circle cx="7" cy="7" r="5.5" stroke={c} strokeWidth="1.5" strokeDasharray={st === "backlog" ? "2.2 2.2" : undefined} fill={st === "done" ? c : "none"} />
      {st === "in_progress" && <path d="M7 7V3A4 4 0 0 1 7 11Z" fill={c} />}
      {st === "review" && <path d="M7 7V3A4 4 0 1 1 3 7Z" fill={c} />}
      {st === "done" && <path d="M4.6 7.2l1.7 1.7 3.2-3.4" stroke="#0b0b10" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />}
    </svg>
  );
}
function PriIcon({ p, size = 14 }: { p: string; size?: number }) {
  const m = PRI[p] || PRI.low;
  return (
    <svg width={size} height={size} viewBox="0 0 14 14">
      {[0, 1, 2, 3].map((i) => (<rect key={i} x={1 + i * 3.3} y={13 - (3 + i * 2.5)} width="2.3" height={3 + i * 2.5} rx="0.8" fill={m.color} fillOpacity={i < m.bars ? 1 : 0.22} />))}
    </svg>
  );
}
function dueInfo(due: string, today: string, done: boolean) {
  if (!due) return null;
  const d = due.slice(0, 10);
  const diff = today ? Math.round((Date.parse(d) - Date.parse(today)) / 86400000) : 99;
  const label = diff === 0 ? "Today" : diff === 1 ? "Tomorrow" : new Date(d + "T00:00:00").toLocaleDateString("en-US", { month: "short", day: "numeric" });
  return { label, tone: done ? "ok" : diff < 0 ? "late" : diff <= 2 ? "soon" : "ok" };
}
const TONE_CLS: Record<string, string> = { late: "text-[#FF7B7B]", soon: "text-[#FFB86B]", ok: "text-muted-foreground" };
function ago(iso: string, nowMs: number): string {
  const m = Math.max(0, Math.round((nowMs - Date.parse(iso)) / 60000));
  return !nowMs || isNaN(m) ? "" : m < 1 ? "just now" : m < 60 ? m + "m ago" : m < 1440 ? Math.round(m / 60) + "h ago" : Math.round(m / 1440) + "d ago";
}

/* shell */
function Mark({ size = 30 }: { size?: number }) {
  return (
    <span style={{ width: size, height: size }} className="grid shrink-0 place-items-center rounded-[10px] bg-gradient-to-br from-primary to-[#B39BFF] shadow-[0_6px_18px_-4px_hsl(var(--primary)/0.7)]">
      <svg width={size / 2} height={size / 2} viewBox="0 0 18 18" fill="none"><rect x="2" y="2" width="4" height="14" rx="1.4" fill="#fff" /><rect x="7" y="2" width="4" height="9" rx="1.4" fill="#fff" fillOpacity=".85" /><rect x="12" y="2" width="4" height="6" rx="1.4" fill="#fff" fillOpacity=".7" /></svg>
    </span>
  );
}
const NAV = [
  { id: "board", label: "Board", to: "/board", Icon: LayoutGrid, mgr: false },
  { id: "work", label: "My work", to: "/my-work", Icon: ListChecks, mgr: false },
  { id: "projects", label: "Projects", to: "/projects", Icon: Layers, mgr: true },
  { id: "team", label: "Team", to: "/team", Icon: Users, mgr: true },
];
function Shell({ app, view, title, actions, children }: { app: AppHandle; view: string; title: string; actions?: React.ReactNode; children: React.ReactNode }) {
  const items = NAV.filter((i) => !i.mgr || app.user.role === "manager");
  const out = () => void app.auth.signOut();
  return (
    <div className="flex h-[100dvh] w-full overflow-hidden bg-background text-foreground">
      <aside className="hidden w-60 shrink-0 flex-col border-r border-border bg-card/30 p-4 lg:flex">
        <div className="flex items-center gap-2.5 px-1"><Mark /><span className="text-[15px] font-semibold tracking-tight">Kanbo</span></div>
        <nav className="mt-6 flex flex-col gap-0.5">
          {items.map((it) => (
            <button key={it.id} onClick={() => app.navigate(it.to)} className={"relative flex h-9 items-center gap-2.5 rounded-lg px-2.5 text-[13px] font-medium " + (view === it.id ? "text-foreground" : "text-muted-foreground hover:text-foreground")}>
              {view === it.id && <motion.span layoutId="nav-pill" transition={SPRING} className="absolute inset-0 rounded-lg bg-primary/15 ring-1 ring-primary/30" />}
              <it.Icon className={"relative h-4 w-4 " + (view === it.id ? "text-primary" : "")} /><span className="relative">{it.label}</span>
            </button>
          ))}
        </nav>
        <div className="mt-auto flex items-center gap-1.5 px-1 text-[11px] text-muted-foreground"><Zap className="h-3.5 w-3.5 text-[#F2B94B]" />WIP limit: 3 each</div>
        <div className="mt-3 flex items-center gap-2.5 rounded-xl border border-border bg-card/60 p-2.5">
          <Av name={app.user.name || "You"} size={30} />
          <div className="min-w-0 flex-1"><div className="truncate text-[12px] font-medium">{app.user.name}</div><div className="text-[10px] capitalize text-muted-foreground">{app.user.role}</div></div>
          <button aria-label="Sign out" onClick={out} className="rounded-md p-1.5 text-muted-foreground hover:bg-muted hover:text-foreground"><LogOut className="h-4 w-4" /></button>
        </div>
      </aside>
      <div className="flex min-w-0 flex-1 flex-col">
        <header className="flex h-14 shrink-0 items-center gap-3 border-b border-border px-4 lg:px-6">
          <span className="lg:hidden"><Mark size={28} /></span>
          <h1 className="text-[15px] font-semibold tracking-tight">{title}</h1>
          <div className="ml-auto flex items-center gap-2">{actions}<button aria-label="Sign out" onClick={out} className="rounded-md p-2 text-muted-foreground hover:bg-muted lg:hidden"><LogOut className="h-4 w-4" /></button></div>
        </header>
        <main className="min-h-0 flex-1 overflow-y-auto pb-[84px] lg:pb-0">{children}</main>
        <nav className="fixed inset-x-0 bottom-0 z-40 flex border-t border-border bg-background/80 px-2 pb-[max(env(safe-area-inset-bottom),6px)] pt-1.5 backdrop-blur-xl lg:hidden">
          {items.map((it) => (
            <button key={it.id} onClick={() => app.navigate(it.to)} className={"relative flex flex-1 flex-col items-center gap-0.5 py-1.5 text-[10px] font-medium " + (view === it.id ? "text-primary" : "text-muted-foreground")}>
              {view === it.id && <motion.span layoutId="tab-dot" transition={SPRING} className="absolute -top-1.5 h-0.5 w-8 rounded-full bg-primary" />}
              <it.Icon className="h-5 w-5" />{it.label}
            </button>
          ))}
        </nav>
      </div>
    </div>
  );
}

/* card */
type CardProps = { c: R; code: string; who: string; items: R[]; flash: boolean; today: string; mobile: boolean; canDrag: boolean; reduce: boolean; open: () => void; onStart: () => void; onMove: (x: number, y: number) => void; onDrop: (x: number, y: number) => void; reg: (el: HTMLElement | null) => void };
function KCard({ c, code, who, items, flash, today, mobile, canDrag, reduce, open, onStart, onMove, onDrop, reg }: CardProps) {
  const controls = useDragControls();
  const labels = s(c.labels).split(",").map((x) => x.trim()).filter(Boolean).slice(0, 2);
  const done = items.filter((i) => !!i.done).length;
  const di = dueInfo(s(c.due), today, s(c.stage) === "done");
  const late = s(c.stage) !== "done" && (di?.tone === "late" || !!c.overdue);
  return (
    <motion.div
      ref={reg}
      layout
      layoutId={"card-" + s(c.id)}
      transition={reduce ? { duration: 0 } : SPRING}
      initial={reduce ? false : { opacity: 0, y: 8 }}
      animate={{ opacity: 1, y: 0 }}
      drag={canDrag}
      dragControls={controls}
      dragListener={!mobile}
      dragSnapToOrigin
      dragMomentum={false}
      dragElastic={0.06}
      onDragStart={onStart}
      onDrag={(_e: unknown, info: PanInfo) => onMove(info.point.x, info.point.y)}
      onDragEnd={(_e: unknown, info: PanInfo) => onDrop(info.point.x, info.point.y)}
      onTap={open}
      whileHover={reduce ? undefined : { y: -1 }}
      whileDrag={reduce ? { zIndex: 60 } : { scale: 1.035, rotate: 1.2, zIndex: 60, boxShadow: "0 24px 48px -12px rgba(0,0,0,0.6), 0 0 0 1px hsl(var(--primary)/0.5)" }}
      whileTap={reduce ? undefined : { scale: 0.985 }}
      style={{ touchAction: mobile ? "pan-y" : "none" }}
      className={"relative cursor-grab select-none rounded-xl border bg-card p-3 shadow-[0_1px_0_hsl(var(--foreground)/0.04),0_6px_16px_-8px_rgba(0,0,0,0.5)] active:cursor-grabbing " + (flash ? "border-primary ring-2 ring-primary/40" : "border-border hover:border-foreground/20")}
    >
      <div className="flex items-center gap-2 text-[10px] font-medium tracking-wide text-muted-foreground">
        <span className="rounded bg-muted px-1.5 py-0.5 font-mono">{code}</span>
        {late && <span className="flex items-center gap-1 text-[#FF7B7B]"><AlertCircle className="h-3 w-3" />Overdue</span>}
        <span className="ml-auto flex items-center gap-1.5"><PriIcon p={s(c.priority)} />
          {mobile && canDrag && <span onPointerDown={(e) => { e.stopPropagation(); controls.start(e); }} style={{ touchAction: "none" }} className="-mr-1 grid h-7 w-6 place-items-center rounded-md text-muted-foreground/70 active:bg-muted"><svg width="10" height="14" viewBox="0 0 10 14" fill="currentColor"><circle cx="2" cy="2" r="1.3" /><circle cx="8" cy="2" r="1.3" /><circle cx="2" cy="7" r="1.3" /><circle cx="8" cy="7" r="1.3" /><circle cx="2" cy="12" r="1.3" /><circle cx="8" cy="12" r="1.3" /></svg></span>}
        </span>
      </div>
      <div className="mt-1.5 text-[13px] font-medium leading-snug text-foreground">{s(c.title)}</div>
      {labels.length > 0 && (
        <div className="mt-2 flex flex-wrap gap-1">
          {labels.map((l) => (<span key={l} className="inline-flex items-center gap-1 rounded-full border border-border px-1.5 py-0.5 text-[10px] text-muted-foreground"><span className="h-1.5 w-1.5 rounded-full" style={{ background: LCOL[hash(l) % LCOL.length] }} />{l}</span>))}
        </div>
      )}
      <div className="mt-2.5 flex items-center gap-2.5 text-[11px]">
        {di && <span className={"flex items-center gap-1 " + TONE_CLS[late ? "late" : di.tone]}><CalendarDays className="h-3 w-3" />{di.label}</span>}
        {items.length > 0 && <span className="flex items-center gap-1 text-muted-foreground"><Check className="h-3 w-3" />{done}/{items.length}</span>}
        <span className="ml-auto">{who ? <Av name={who} size={22} /> : <span className="grid h-[22px] w-[22px] place-items-center rounded-full border border-dashed border-border text-[9px] text-muted-foreground">?</span>}</span>
      </div>
    </motion.div>
  );
}

/* sheet */
type SheetProps = { app: AppHandle; card: R; projects: R[]; members: R[]; wip: Record<string, number>; items: R[]; comments: R[]; canEdit: boolean; isMgr: boolean; today: string; nowMs: number; desk: boolean; reduce: boolean; onClose: () => void; onStage: (st: string) => void; toast: (t: string, tone?: string) => void };
function Sheet({ app, card, projects, members, wip, items, comments, canEdit, isMgr, today, nowMs, desk, reduce, onClose, onStage, toast }: SheetProps) {
  const id = s(card.id);
  const project = projects.find((p) => s(p.id) === s(card.project));
  const [title, setTitle] = useState(s(card.title));
  const [desc, setDesc] = useState(s(card.description));
  const [newItem, setNewItem] = useState("");
  const [body, setBody] = useState("");
  const [ai, setAi] = useState(false);
  const [sugg, setSugg] = useState<string[]>([]);
  const [aiErr, setAiErr] = useState("");
  useEffect(() => { setTitle(s(card.title)); setDesc(s(card.description)); }, [id, card.title, card.description]);
  const sorted = [...items].sort((a, b) => n(a.position) - n(b.position));
  const doneN = sorted.filter((i) => !!i.done).length;
  const pct = sorted.length ? Math.round((doneN / sorted.length) * 100) : 0;
  const nextPos = () => sorted.reduce((m, i) => Math.max(m, n(i.position)), 0) + 1;
  const save = async (patch: R) => { try { await app.update("card", id, patch); } catch (e) { toast(msg(e), "error"); } };
  const assign = async (mid: string) => {
    try {
      await app.update("card", id, { assignee: mid || null });
      if (mid) await app.create("assignment", { card: id, assignee: mid, by: app.user.name, title: s(card.title) });
      toast(mid ? "Assigned — they've been notified" : "Unassigned");
    } catch (e) { toast(msg(e), "error"); }
  };
  const addItem = async (text: string, pos: number) => { await app.create("checklist_item", { card: id, text, done: false, position: pos }); };
  const breakDown = async () => {
    if (ai) return;
    setAi(true); setAiErr(""); setSugg([]);
    let steps: string[] = [];
    try {
      const raw = await app.ai.ask("Break this task into 3 to 6 concrete checklist steps.\nTask: " + s(card.title) + "\nContext: " + s(card.description) + "\nReply with one short imperative step per line. No numbering, no bullets, no extra text.", { system: "You are a concise engineering project assistant.", maxTokens: 220 });
      steps = raw.split("\n").map((l) => l.replace(/^[\s\-*\d.)]+/, "").trim()).filter((l) => l.length > 2).slice(0, 6);
    } catch { steps = []; }
    if (steps.length < 3) setAiErr("AI is resting right now, try again soon."); else setSugg(steps);
    setAi(false);
  };
  const addSteps = async (list: string[]) => {
    try {
      const base = nextPos();
      for (let i = 0; i < list.length; i++) await addItem(list[i], base + i);
      setSugg((p) => p.filter((x) => !list.includes(x)));
    } catch (e) { toast(msg(e), "error"); }
  };
  const send = async () => {
    const t = body.trim(); if (!t) return; setBody("");
    try { await app.create("comment", { card: id, assignee: s(card.assignee) || null, author: app.user.name, body: t }); } catch (e) { toast(msg(e), "error"); setBody(t); }
  };
  const cm = [...comments].sort((a, b) => Date.parse(s(a.created_at)) - Date.parse(s(b.created_at)));
  const di = dueInfo(s(card.due), today, s(card.stage) === "done");
  const row = "flex items-start gap-3 py-2";
  const lbl = "w-[72px] shrink-0 pt-1 text-[12px] text-muted-foreground";
  const pill = (on: boolean) => "flex items-center gap-1.5 rounded-full border px-2 py-1 text-[11px] font-medium transition disabled:opacity-60 " + (on ? "border-primary/50 bg-primary/10 text-foreground" : "border-transparent text-muted-foreground hover:text-foreground");
  const h = "text-[11px] font-semibold uppercase tracking-[0.12em] text-muted-foreground";
  const panel = desk ? { initial: { x: 48, opacity: 0 }, animate: { x: 0, opacity: 1 }, exit: { x: 48, opacity: 0 } } : { initial: { y: "100%" }, animate: { y: 0 }, exit: { y: "100%" } };
  return (
    <>
      <motion.div className="fixed inset-0 z-50 bg-black/55 backdrop-blur-[2px]" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={onClose} />
      <motion.aside {...panel} transition={reduce ? { duration: 0 } : { type: "spring", stiffness: 380, damping: 38 }} className={"fixed z-50 flex flex-col overflow-hidden border-border bg-card " + (desk ? "bottom-0 right-0 top-0 w-[520px] border-l" : "inset-x-0 bottom-0 top-8 rounded-t-3xl border-t")}>
        {!desk && <div className="mx-auto mt-2 h-1 w-10 rounded-full bg-border" />}
        <div className="flex items-center gap-2 px-5 pb-1 pt-4 text-[11px] text-muted-foreground">
          <span className="rounded bg-muted px-1.5 py-0.5 font-mono">{s(project?.code)}</span><span className="truncate">{s(project?.name)}</span>
          <button onClick={onClose} aria-label="Close" className="ml-auto rounded-md p-1.5 hover:bg-muted"><X className="h-4 w-4" /></button>
        </div>
        <div className="min-h-0 flex-1 overflow-y-auto px-5 pb-8">
          <input value={title} readOnly={!canEdit} onChange={(e) => setTitle(e.target.value)} onBlur={() => { if (canEdit && title.trim() && title !== s(card.title)) void save({ title: title.trim() }); }} className="w-full bg-transparent text-[20px] font-semibold leading-tight tracking-tight outline-none" />
          {!canEdit && <div className="mt-1 text-[11px] text-muted-foreground">Read-only. You can still comment.</div>}
          <div className="mt-4 divide-y divide-border/60 rounded-xl border border-border bg-background/40 px-3.5">
            <div className={row}><span className={lbl}>Stage</span>
              <div className="flex flex-wrap gap-0.5">{STAGES.map((st) => (
                <button key={st} disabled={!canEdit} onClick={() => onStage(st)} className={"relative " + pill(false)}>
                  {s(card.stage) === st && <motion.span layoutId="stage-pill" transition={SPRING} className="absolute inset-0 rounded-full bg-muted ring-1 ring-border" />}
                  <span className={"relative flex items-center gap-1.5 " + (s(card.stage) === st ? "text-foreground" : "")}><StageIcon st={st} size={12} />{ST_LABEL[st]}</span>
                </button>))}</div></div>
            <div className={row}><span className={lbl}>Priority</span>
              <div className="flex flex-wrap gap-0.5">{Object.keys(PRI).map((p) => (<button key={p} disabled={!canEdit} onClick={() => void save({ priority: p })} className={pill(s(card.priority) === p)}><PriIcon p={p} size={12} />{PRI[p].label}</button>))}</div></div>
            <div className={row}><span className={lbl}>Assignee</span>
              <div className="flex flex-wrap gap-0.5">
                <button disabled={!canEdit} onClick={() => void assign("")} className={pill(!s(card.assignee))}>Unassigned</button>
                {members.map((m) => { const mid = s(m.id); const w = wip[mid] || 0; return (
                  <button key={mid} disabled={!canEdit} onClick={() => void assign(mid)} className={pill(s(card.assignee) === mid) + " !py-0.5 !pl-0.5"}><Av name={s(m.name)} size={18} />{s(m.name).split(" ")[0]}<span className={"text-[9px] " + (w >= 3 ? "text-[#FF8A5B]" : "text-muted-foreground/70")}>{w}/3</span></button>); })}
              </div></div>
            {isMgr && <div className={row}><span className={lbl}>Project</span>
              <div className="flex flex-wrap gap-0.5">{projects.map((p) => (<button key={s(p.id)} onClick={() => void save({ project: s(p.id) })} className={pill(s(card.project) === s(p.id)) + " font-mono"}>{s(p.code)}</button>))}</div></div>}
            <div className={row + " items-center"}><span className={lbl + " pt-0"}>Due</span>
              <input type="date" disabled={!canEdit} value={s(card.due).slice(0, 10)} onChange={(e) => void save({ due: e.target.value || null })} className={"rounded-md border border-border bg-transparent px-2 py-1 text-[12px] outline-none focus:border-primary " + (di ? TONE_CLS[di.tone] : "")} /></div>
          </div>
          <div className={"mt-5 " + h}>Description</div>
          <textarea value={desc} readOnly={!canEdit} rows={3} placeholder="Add context, links, acceptance criteria…" onChange={(e) => setDesc(e.target.value)} onBlur={() => { if (canEdit && desc !== s(card.description)) void save({ description: desc }); }} className="-ml-2 mt-1.5 w-full resize-none rounded-xl border border-transparent bg-transparent p-2 text-[13px] leading-relaxed text-foreground/90 outline-none hover:border-border focus:border-primary" />
          <div className="mt-5 flex items-center gap-2">
            <span className={h}>Checklist</span><span className="text-[11px] text-muted-foreground">{doneN}/{sorted.length}</span>
            <motion.button whileTap={reduce ? undefined : { scale: 0.95 }} disabled={ai || !canEdit} onClick={() => void breakDown()} className="ml-auto flex items-center gap-1.5 rounded-full bg-gradient-to-r from-primary/25 to-[#B39BFF]/20 px-3 py-1.5 text-[11px] font-medium text-foreground ring-1 ring-primary/40 disabled:opacity-60">
              {ai ? <RefreshCw className="h-3.5 w-3.5 animate-spin" /> : <Sparkles className="h-3.5 w-3.5 text-primary" />}{ai ? "Thinking…" : "Break it down"}
            </motion.button>
          </div>
          <div className="mt-2 h-1.5 overflow-hidden rounded-full bg-muted"><motion.div className="h-full rounded-full bg-gradient-to-r from-primary to-[#B39BFF]" animate={{ width: pct + "%" }} transition={reduce ? { duration: 0 } : { type: "spring", stiffness: 140, damping: 22 }} /></div>
          {(sugg.length > 0 || aiErr) && (
            <div className="mt-3 rounded-xl border border-primary/30 bg-primary/5 p-3 text-[13px]">
              {aiErr ? <div className="text-[12px] text-muted-foreground">{aiErr}</div> : (<>
                <div className="flex items-center gap-2 text-[11px] font-medium"><Sparkles className="h-3.5 w-3.5 text-primary" />Suggested steps<button onClick={() => void addSteps(sugg)} className="ml-auto rounded-full bg-primary px-2.5 py-1 font-semibold text-primary-foreground">Add all</button></div>
                {sugg.map((st) => (<button key={st} onClick={() => void addSteps([st])} className="mt-1 flex w-full items-center gap-2 rounded-lg bg-background/60 px-2.5 py-1.5 text-left hover:bg-primary/10"><Plus className="h-3.5 w-3.5 shrink-0 text-primary" />{st}</button>))}
              </>)}
            </div>
          )}
          <div className="mt-2 flex flex-col">
            <AnimatePresence initial={false}>
              {sorted.map((it) => { const k = s(it.id); const d = !!it.done; return (
                <motion.div key={k} layout="position" initial={reduce ? false : { opacity: 0, x: -10 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, height: 0 }} className="flex items-center gap-2.5 rounded-lg px-1 py-1.5 hover:bg-muted/50">
                  <motion.button whileTap={reduce ? undefined : { scale: 0.8 }} disabled={!canEdit} onClick={() => void app.update("checklist_item", k, { done: !d }).catch((e) => toast(msg(e), "error"))} aria-label="Toggle" className={"grid h-[18px] w-[18px] shrink-0 place-items-center rounded-md border transition " + (d ? "border-primary bg-primary text-primary-foreground" : "border-border")}>{d && <Check className="h-3 w-3" />}</motion.button>
                  <span className={"flex-1 text-[13px] " + (d ? "text-muted-foreground line-through" : "")}>{s(it.text)}</span>
                </motion.div>); })}
            </AnimatePresence>
            {canEdit && (
              <div className="mt-1 flex items-center gap-2 px-1"><Plus className="h-4 w-4 text-muted-foreground" />
                <input value={newItem} onChange={(e) => setNewItem(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter" && newItem.trim()) { const t = newItem.trim(); setNewItem(""); void addItem(t, nextPos()).catch((er) => toast(msg(er), "error")); } }} placeholder="Add an item" className="h-8 flex-1 bg-transparent text-[13px] outline-none placeholder:text-muted-foreground/60" /></div>)}
          </div>
          <div className={"mt-6 flex items-center gap-2 " + h}><MessageSquare className="h-3.5 w-3.5" />Comments<span className="font-normal">{cm.length}</span></div>
          <div className="mt-3 flex flex-col gap-3">
            <AnimatePresence initial={false}>
              {cm.map((c) => (
                <motion.div key={s(c.id)} layout initial={reduce ? false : { opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} className="flex gap-2.5">
                  <Av name={s(c.author)} size={26} />
                  <div className="min-w-0 flex-1 rounded-xl rounded-tl-sm bg-muted/60 px-3 py-2"><div className="flex items-baseline gap-2"><span className="text-[12px] font-medium">{s(c.author)}</span><span className="text-[10px] text-muted-foreground">{ago(s(c.created_at), nowMs)}</span></div><div className="mt-0.5 text-[13px] leading-snug text-foreground/90">{s(c.body)}</div></div>
                </motion.div>))}
            </AnimatePresence>
            {cm.length === 0 && <div className="rounded-xl border border-dashed border-border px-3 py-4 text-center text-[12px] text-muted-foreground">No comments yet.</div>}
          </div>
          <div className="mt-3 flex items-center gap-2 rounded-xl border border-border bg-background/50 py-1.5 pl-3 pr-1.5 focus-within:border-primary">
            <input value={body} onChange={(e) => setBody(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter") void send(); }} placeholder="Write a comment…" className="h-8 flex-1 bg-transparent text-[13px] outline-none placeholder:text-muted-foreground/60" />
            <motion.button whileTap={reduce ? undefined : { scale: 0.88 }} onClick={() => void send()} aria-label="Send" className="grid h-8 w-8 place-items-center rounded-lg bg-primary text-primary-foreground"><Send className="h-4 w-4" /></motion.button>
          </div>
        </div>
      </motion.aside>
    </>
  );
}

/* board */
type Toast = { id: number; text: string; tone: string };
export default function KanboBoard({ app, openId }: Props) {
  const reduce = !!useReducedMotion();
  if (!app) return <div className="p-6 text-sm text-muted-foreground">Loading…</div>;
  return <BoardInner app={app} openId={openId} reduce={reduce} />;
}
function BoardInner({ app, openId, reduce }: { app: AppHandle; openId?: string; reduce: boolean }) {
  const cardsRaw = app.rows("card") as R[];
  const members = app.rows("member") as R[];
  const projects = app.rows("project") as R[];
  const itemsAll = app.rows("checklist_item") as R[];
  const commentsAll = app.rows("comment") as R[];
  const isMgr = app.user.role === "manager";
  const mineId = app.me("member") || "";
  const [ovr, setOvr] = useState<Record<string, { stage: string; position: number }>>({});
  const [q, setQ] = useState("");
  const [proj, setProj] = useState("all");
  const [onlyMine, setOnlyMine] = useState(false);
  const [openCard, setOpenCard] = useState<string>(openId || app.params.id || "");
  const [desk, setDesk] = useState(true);
  const [tab, setTab] = useState("in_progress");
  const [hover, setHover] = useState("");
  const [dragId, setDragId] = useState("");
  const [flash, setFlash] = useState<Record<string, boolean>>({});
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [today, setToday] = useState("");
  const [nowMs, setNowMs] = useState(0);
  const targets = useRef<Record<string, HTMLElement | null>>({});
  const cardEls = useRef<Record<string, HTMLElement | null>>({});
  const prev = useRef<Record<string, string> | null>(null);
  const tid = useRef(0);

  useEffect(() => {
    const d = new Date();
    setToday(d.getFullYear() + "-" + String(d.getMonth() + 1).padStart(2, "0") + "-" + String(d.getDate()).padStart(2, "0"));
    setNowMs(d.getTime());
    const mq = window.matchMedia("(min-width: 1024px)");
    const f = () => setDesk(mq.matches);
    f();
    mq.addEventListener("change", f);
    return () => mq.removeEventListener("change", f);
  }, []);
  useEffect(() => {
    const offs = ["card", "checklist_item", "comment", "member", "project"].map((e) => app.live(e));
    return () => offs.forEach((o) => o());
  }, []);

  const toast = useCallback((text: string, tone = "ok") => {
    const id = ++tid.current;
    setToasts((t) => [...t.slice(-2), { id, text, tone }]);
    setTimeout(() => setToasts((t) => t.filter((x) => x.id !== id)), 3600);
  }, []);

  const cards = useMemo(() => cardsRaw.map((c) => (ovr[s(c.id)] ? { ...c, ...ovr[s(c.id)] } : c)), [cardsRaw, ovr]);
  useEffect(() => {
    const done = Object.keys(ovr).filter((id) => { const c = cardsRaw.find((x) => s(x.id) === id); return c && s(c.stage) === ovr[id].stage && n(c.position) === ovr[id].position; });
    if (done.length) setOvr((o) => { const r = { ...o }; done.forEach((d) => delete r[d]); return r; });
  }, [cardsRaw, ovr]);
  useEffect(() => {
    const cur: Record<string, string> = {};
    cardsRaw.forEach((c) => { cur[s(c.id)] = s(c.stage); });
    const p = prev.current;
    if (p && cardsRaw.length) {
      const ch = Object.keys(cur).filter((id) => p[id] && p[id] !== cur[id] && !ovr[id]);
      if (ch.length) {
        setFlash((f) => { const r = { ...f }; ch.forEach((i) => (r[i] = true)); return r; });
        toast("Live: “" + s(cardsRaw.find((x) => s(x.id) === ch[0])?.title) + "” moved to " + ST_LABEL[cur[ch[0]]], "live");
        setTimeout(() => setFlash((f) => { const r = { ...f }; ch.forEach((i) => delete r[i]); return r; }), 2200);
      }
    }
    if (cardsRaw.length) prev.current = cur;
  }, [cardsRaw]);

  const mById = useMemo(() => { const m: Record<string, R> = {}; members.forEach((x) => (m[s(x.id)] = x)); return m; }, [members]);
  const pById = useMemo(() => { const m: Record<string, R> = {}; projects.forEach((x) => (m[s(x.id)] = x)); return m; }, [projects]);
  const itemsBy = useMemo(() => { const m: Record<string, R[]> = {}; itemsAll.forEach((x) => { (m[s(x.card)] = m[s(x.card)] || []).push(x); }); return m; }, [itemsAll]);
  const wip = useMemo(() => { const m: Record<string, number> = {}; cards.forEach((c) => { if (s(c.stage) === "in_progress" && s(c.assignee)) m[s(c.assignee)] = (m[s(c.assignee)] || 0) + 1; }); return m; }, [cards]);
  const byStage = useMemo(() => {
    const m: Record<string, R[]> = {}; STAGES.forEach((st) => (m[st] = []));
    cards.filter((c) => (proj === "all" || s(c.project) === proj) && (!onlyMine || s(c.assignee) === mineId) && (!q || s(c.title).toLowerCase().includes(q.toLowerCase()))).forEach((c) => { (m[s(c.stage)] || (m[s(c.stage)] = [])).push(c); });
    STAGES.forEach((st) => m[st].sort((a, b) => n(a.position) - n(b.position)));
    return m;
  }, [cards, proj, onlyMine, q, mineId]);

  const canEdit = (c: R) => isMgr || (!!mineId && s(c.assignee) === mineId);
  const hit = (x: number, y: number): string => {
    let best = ""; let bd = 1e9;
    for (const st of STAGES) {
      const el = targets.current[st]; if (!el) continue;
      const r = el.getBoundingClientRect(); if (r.width === 0) continue;
      if (desk) { const d = x < r.left ? r.left - x : x > r.right ? x - r.right : 0; if (y > r.top - 60 && d < bd) { bd = d; best = st; } }
      else if (x >= r.left - 4 && x <= r.right + 4 && y >= r.top - 4 && y <= r.bottom + 4) best = st;
    }
    return best;
  };
  const commit = async (c: R, st: string, pos: number) => {
    const id = s(c.id); const from = s(c.stage);
    if (from === st && Math.abs(pos - n(c.position)) < 0.001) return;
    setOvr((o) => ({ ...o, [id]: { stage: st, position: pos } }));
    try {
      await app.update("card", id, { stage: st, position: pos });
      if (st !== from) toast("Moved to " + ST_LABEL[st]);
    } catch (e) {
      setOvr((o) => { const r = { ...o }; delete r[id]; return r; });
      toast(msg(e), "error");
    }
    setTimeout(() => setOvr((o) => { const r = { ...o }; delete r[id]; return r; }), 4000);
  };
  const drop = (c: R, x: number, y: number) => {
    setDragId(""); setHover("");
    const id = s(c.id);
    const target = hit(x, y);
    const st = target || (desk ? "" : tab);
    if (!st) return;
    if (!canEdit(c)) { toast("Only the assignee or a manager can move this card", "error"); return; }
    const list = (byStage[st] || []).filter((o) => s(o.id) !== id);
    let idx = list.length;
    if (desk || !target || target === tab) {
      idx = 0;
      for (const o of list) { const el = cardEls.current[s(o.id)]; if (!el) continue; const r = el.getBoundingClientRect(); if (y > r.top + r.height / 2) idx++; else break; }
    }
    const a = idx > 0 ? n(list[idx - 1].position) : null; const b = idx < list.length ? n(list[idx].position) : null;
    void commit(c, st, a !== null && b !== null ? (a + b) / 2 : a !== null ? a + 1000 : b !== null ? b / 2 : 1000);
  };
  const stageFromSheet = (c: R, st: string) => {
    if (s(c.stage) === st) return;
    const l = (byStage[st] || []).filter((o) => s(o.id) !== s(c.id));
    void commit(c, st, l.length ? n(l[l.length - 1].position) + 1000 : 1000);
  };
  const createCard = async () => {
    try {
      const row = await app.create("card", { title: "Untitled card", project: s(projects[0]?.id), stage: "backlog", priority: "medium", position: (cards.length + 2) * 1000 + (nowMs % 997) });
      setOpenCard(s(row.id));
    } catch (e) { toast(msg(e), "error"); }
  };

  const sel = cards.find((c) => s(c.id) === openCard);
  const close = () => { setOpenCard(""); if (app.params.id) app.navigate("/board"); };

  const actions = isMgr ? (
    <motion.button whileTap={reduce ? undefined : { scale: 0.95 }} whileHover={reduce ? undefined : { y: -1 }} onClick={() => void createCard()} className="flex h-8 items-center gap-1.5 rounded-lg bg-primary px-3 text-[12px] font-semibold text-primary-foreground shadow-[0_6px_18px_-6px_hsl(var(--primary)/0.9),inset_0_1px_0_rgba(255,255,255,0.25)]">
      <Plus className="h-3.5 w-3.5" />New card
    </motion.button>
  ) : null;
  const colCard = (c: R) => (
    <KCard key={s(c.id)} c={c} code={s(pById[s(c.project)]?.code)} who={s(mById[s(c.assignee)]?.name)} items={itemsBy[s(c.id)] || []} flash={!!flash[s(c.id)]} today={today} mobile={!desk} canDrag={canEdit(c)} reduce={reduce}
      open={() => setOpenCard(s(c.id))} onStart={() => setDragId(s(c.id))} onMove={(x, y) => { const h = hit(x, y); setHover((p) => (p === h ? p : h)); }} onDrop={(x, y) => drop(c, x, y)} reg={(el) => { cardEls.current[s(c.id)] = el; }} />
  );

  return (
    <Shell app={app} view="board" title="Board" actions={actions}>
      <div className="flex flex-col gap-3 px-4 pb-3 pt-3 lg:px-6">
        <div className="flex flex-wrap items-center gap-2">
          <div className="flex h-9 min-w-0 flex-1 items-center gap-2 rounded-xl border border-border bg-card/60 px-3 focus-within:border-primary lg:max-w-xs"><Search className="h-4 w-4 text-muted-foreground" /><input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Filter cards" className="h-full min-w-0 flex-1 bg-transparent text-[13px] outline-none placeholder:text-muted-foreground/60" /></div>
          <button onClick={() => setOnlyMine((v) => !v)} className={"flex h-9 items-center rounded-xl border px-3 text-[12px] font-medium transition " + (onlyMine ? "border-primary/50 bg-primary/15 text-foreground" : "border-border bg-card/60 text-muted-foreground")}>Only mine</button>
        </div>
        <div className="-mx-4 flex gap-1.5 overflow-x-auto px-4 pb-0.5 lg:mx-0 lg:px-0 [scrollbar-width:none]">
          {[{ id: "all", code: "All projects" }, ...projects.map((p) => ({ id: s(p.id), code: s(p.code) }))].map((p) => (
            <button key={p.id} onClick={() => setProj(p.id)} className={"relative shrink-0 rounded-full px-3 py-1 text-[11px] font-medium transition " + (proj === p.id ? "text-foreground" : "text-muted-foreground hover:text-foreground")}>
              {proj === p.id && <motion.span layoutId="proj-chip" transition={SPRING} className="absolute inset-0 rounded-full bg-muted ring-1 ring-border" />}<span className="relative">{p.code}</span>
            </button>))}
        </div>
      </div>

      {!desk && (
        <div className="sticky top-0 z-20 flex gap-1 overflow-x-auto bg-background/90 px-4 pb-2 pt-1 backdrop-blur-xl [scrollbar-width:none]">
          {STAGES.map((st) => (
            <button key={st} ref={(el) => { targets.current[st] = el; }} onClick={() => setTab(st)} className={"relative flex shrink-0 items-center gap-1.5 rounded-full px-3 py-1.5 text-[12px] font-medium transition " + (tab === st ? "text-foreground" : "text-muted-foreground") + (dragId && hover === st ? " bg-primary/20 ring-2 ring-primary" : "")}>
              {tab === st && <motion.span layoutId="tab-pill" transition={SPRING} className="absolute inset-0 rounded-full bg-muted ring-1 ring-border" />}
              <span className="relative flex items-center gap-1.5"><StageIcon st={st} size={13} />{ST_LABEL[st]}<span className="text-[10px] text-muted-foreground">{(byStage[st] || []).length}</span></span>
            </button>))}
        </div>
      )}

      <LayoutGroup>
        {desk ? (
          <div className="flex items-start gap-3 px-6 pb-8">
            {STAGES.map((st) => { const list = byStage[st] || []; return (
              <div key={st} ref={(el) => { targets.current[st] = el; }} className={"min-w-[200px] flex-1 rounded-2xl border p-2 transition-colors " + (dragId && hover === st ? "border-primary/60 bg-primary/10" : "border-border/60 bg-muted/20")}>
                <div className="flex items-center gap-2 px-1.5 pb-2 pt-1 text-[12px] font-medium"><StageIcon st={st} />{ST_LABEL[st]}<span className="text-muted-foreground">{list.length}</span></div>
                <div className="flex min-h-[72px] flex-col gap-2">
                  {list.map((c) => colCard(c))}
                  {list.length === 0 && <div className="grid h-[72px] place-items-center rounded-xl border border-dashed border-border text-[11px] text-muted-foreground">Drop a card here</div>}
                </div>
              </div>); })}
          </div>
        ) : (
          <div className="flex flex-col gap-2 px-4 pb-6">
            {(byStage[tab] || []).map((c) => colCard(c))}
            {(byStage[tab] || []).length === 0 && <div className="grid h-40 place-items-center rounded-2xl border border-dashed border-border text-center text-[12px] text-muted-foreground"><div><StageIcon st={tab} size={22} /><div className="mt-2">Nothing in {ST_LABEL[tab]}</div></div></div>}
          </div>
        )}
      </LayoutGroup>

      <AnimatePresence>
        {sel && <Sheet key="sheet" app={app} card={sel} projects={projects} members={members} wip={wip} items={itemsBy[s(sel.id)] || []} comments={commentsAll.filter((c) => s(c.card) === s(sel.id))} canEdit={canEdit(sel)} isMgr={isMgr} today={today} nowMs={nowMs} desk={desk} reduce={reduce} onClose={close} onStage={(st) => stageFromSheet(sel, st)} toast={toast} />}
      </AnimatePresence>

      <div className="pointer-events-none fixed inset-x-0 bottom-24 z-[60] flex flex-col items-center gap-2 lg:bottom-6">
        <AnimatePresence>
          {toasts.map((t) => (
            <motion.div key={t.id} layout initial={{ opacity: 0, y: 16, scale: 0.96 }} animate={{ opacity: 1, y: 0, scale: 1 }} exit={{ opacity: 0, y: 8, scale: 0.96 }} transition={SPRING} className={"pointer-events-auto flex max-w-[92vw] items-center gap-2 rounded-xl border px-3.5 py-2.5 text-[12px] font-medium shadow-[0_16px_40px_-12px_rgba(0,0,0,0.7)] " + (t.tone === "error" ? "border-[#FF6B6B]/40 bg-[#2a1215] text-[#FFB4B4]" : t.tone === "live" ? "border-primary/50 bg-card text-foreground" : "border-border bg-card text-foreground")}>
              {t.tone === "error" ? <AlertCircle className="h-4 w-4 shrink-0" /> : t.tone === "live" ? <Zap className="h-4 w-4 shrink-0 text-primary" /> : <Check className="h-4 w-4 shrink-0 text-[#4CC38A]" />}{t.text}
            </motion.div>))}
        </AnimatePresence>
      </div>
    </Shell>
  );
}

import React, { useEffect, useMemo, useRef, useState } from "react";
import { motion, AnimatePresence, animate, useReducedMotion } from "motion/react";
import { Users, LayoutGrid, ListChecks, Layers, Check, LogOut, Zap, AlertCircle, CalendarDays, ChevronDown, Rocket, Flame, Target, Trophy } from "lucide-react";
import type { AppHandle } from "@app/kit/primitives";

type R = Record<string, unknown>;
type Props = { app?: AppHandle; view?: string };

const s = (v: unknown): string => (v == null ? "" : String(v));
const n = (v: unknown): number => Number(v) || 0;
const STAGES = ["backlog", "todo", "in_progress", "review", "done"];
const ST_LABEL: Record<string, string> = { backlog: "Backlog", todo: "To do", in_progress: "In progress", review: "Review", done: "Done" };
const ST_COLOR: Record<string, string> = { backlog: "#8A8F98", todo: "#B4B8C0", in_progress: "#F2B94B", review: "#5EA2FF", done: "#4CC38A" };
const PRI: Record<string, { label: string; color: string; bars: number }> = {
  urgent: { label: "Urgent", color: "#FF6B6B", bars: 4 },
  high: { label: "High", color: "#FFA94D", bars: 3 },
  medium: { label: "Medium", color: "#FFD43B", bars: 2 },
  low: { label: "Low", color: "#8A8F98", bars: 1 },
};
const GRADS = [["#7C5CFF", "#B39BFF"], ["#14B8A6", "#38BDF8"], ["#EC4899", "#FB923C"], ["#3B82F6", "#818CF8"], ["#10B981", "#A3E635"], ["#F59E0B", "#EF4444"]];
const SPRING = { type: "spring" as const, stiffness: 420, damping: 34 };
const hash = (t: string): number => { let h = 0; for (let i = 0; i < t.length; i++) h = (h * 31 + t.charCodeAt(i)) >>> 0; return h; };
const msg = (e: unknown): string => {
  const m = e instanceof Error ? e.message : s(e);
  return /WIP/i.test(m) ? "WIP limit reached: this teammate already has 3 cards in progress." : m || "Something went wrong";
};

function Av({ name, size = 24 }: { name: string; size?: number }) {
  const g = GRADS[hash(name) % GRADS.length];
  const p = name.trim().split(/\s+/);
  const ini = ((p[0] || "?")[0] + (p.length > 1 ? p[p.length - 1][0] : "")).toUpperCase();
  return (
    <span title={name} style={{ width: size, height: size, fontSize: Math.max(8, size * 0.38), background: `linear-gradient(135deg, ${g[0]}, ${g[1]})` }} className="inline-grid shrink-0 place-items-center rounded-full font-semibold text-white ring-2 ring-card">{ini}</span>
  );
}
function StageIcon({ st, size = 14 }: { st: string; size?: number }) {
  const c = ST_COLOR[st] || "#8A8F98";
  return (
    <svg width={size} height={size} viewBox="0 0 14 14" fill="none">
      <circle cx="7" cy="7" r="5.5" stroke={c} strokeWidth="1.5" strokeDasharray={st === "backlog" ? "2.2 2.2" : undefined} fill={st === "done" ? c : "none"} />
      {st === "in_progress" && <path d="M7 7V3A4 4 0 0 1 7 11Z" fill={c} />}
      {st === "review" && <path d="M7 7V3A4 4 0 1 1 3 7Z" fill={c} />}
      {st === "done" && <path d="M4.6 7.2l1.7 1.7 3.2-3.4" stroke="#0b0b10" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />}
    </svg>
  );
}
function PriIcon({ p, size = 14 }: { p: string; size?: number }) {
  const m = PRI[p] || PRI.low;
  return (
    <svg width={size} height={size} viewBox="0 0 14 14">
      {[0, 1, 2, 3].map((i) => (<rect key={i} x={1 + i * 3.3} y={13 - (3 + i * 2.5)} width="2.3" height={3 + i * 2.5} rx="0.8" fill={m.color} fillOpacity={i < m.bars ? 1 : 0.22} />))}
    </svg>
  );
}
const fmtDate = (d: string): string => new Date(d.slice(0, 10) + "T00:00:00").toLocaleDateString("en-US", { month: "short", day: "numeric" });
function Count({ v, suffix = "" }: { v: number; suffix?: string }) {
  const reduce = useReducedMotion();
  const [x, setX] = useState(0);
  const last = useRef(0);
  useEffect(() => {
    if (reduce) { setX(v); last.current = v; return; }
    const c = animate(last.current, v, { duration: 0.9, ease: "easeOut", onUpdate: (t: number) => { last.current = t; setX(Math.round(t)); } });
    return () => c.stop();
  }, [v, reduce]);
  return <>{x}{suffix}</>;
}

/* shell */
function Mark({ size = 30 }: { size?: number }) {
  return (
    <span style={{ width: size, height: size }} className="grid shrink-0 place-items-center rounded-[10px] bg-gradient-to-br from-primary to-[#B39BFF] shadow-[0_6px_18px_-4px_hsl(var(--primary)/0.7)]">
      <svg width={size / 2} height={size / 2} viewBox="0 0 18 18" fill="none"><rect x="2" y="2" width="4" height="14" rx="1.4" fill="#fff" /><rect x="7" y="2" width="4" height="9" rx="1.4" fill="#fff" fillOpacity=".85" /><rect x="12" y="2" width="4" height="6" rx="1.4" fill="#fff" fillOpacity=".7" /></svg>
    </span>
  );
}
const NAV = [
  { id: "board", label: "Board", to: "/board", Icon: LayoutGrid, mgr: false },
  { id: "work", label: "My work", to: "/my-work", Icon: ListChecks, mgr: false },
  { id: "projects", label: "Projects", to: "/projects", Icon: Layers, mgr: true },
  { id: "team", label: "Team", to: "/team", Icon: Users, mgr: true },
];
function Shell({ app, view, title, children }: { app: AppHandle; view: string; title: string; children: React.ReactNode }) {
  const items = NAV.filter((i) => !i.mgr || app.user.role === "manager");
  const out = () => void app.auth.signOut();
  return (
    <div className="flex h-[100dvh] w-full overflow-hidden bg-background text-foreground">
      <aside className="hidden w-60 shrink-0 flex-col border-r border-border bg-card/30 p-4 lg:flex">
        <div className="flex items-center gap-2.5 px-1"><Mark /><span className="text-[15px] font-semibold tracking-tight">Kanbo</span></div>
        <nav className="mt-6 flex flex-col gap-0.5">
          {items.map((it) => (
            <button key={it.id} onClick={() => app.navigate(it.to)} className={"relative flex h-9 items-center gap-2.5 rounded-lg px-2.5 text-[13px] font-medium " + (view === it.id ? "text-foreground" : "text-muted-foreground hover:text-foreground")}>
              {view === it.id && <motion.span layoutId="nav-pill" transition={SPRING} className="absolute inset-0 rounded-lg bg-primary/15 ring-1 ring-primary/30" />}
              <it.Icon className={"relative h-4 w-4 " + (view === it.id ? "text-primary" : "")} /><span className="relative">{it.label}</span>
            </button>
          ))}
        </nav>
        <div className="mt-auto rounded-xl border border-border bg-gradient-to-br from-primary/10 to-transparent p-3 text-[11px] leading-relaxed text-muted-foreground"><div className="mb-1 flex items-center gap-1.5 font-medium text-foreground"><Zap className="h-3.5 w-3.5 text-[#F2B94B]" />WIP limit: 3</div>Nobody carries more than three cards in progress. Finish one to start the next.</div>
        <div className="mt-3 flex items-center gap-2.5 rounded-xl border border-border bg-card/60 p-2.5">
          <Av name={app.user.name || "You"} size={30} />
          <div className="min-w-0 flex-1"><div className="truncate text-[12px] font-medium">{app.user.name}</div><div className="text-[10px] capitalize text-muted-foreground">{app.user.role}</div></div>
          <button aria-label="Sign out" onClick={out} className="rounded-md p-1.5 text-muted-foreground hover:bg-muted hover:text-foreground"><LogOut className="h-4 w-4" /></button>
        </div>
      </aside>
      <div className="flex min-w-0 flex-1 flex-col">
        <header className="flex h-14 shrink-0 items-center gap-3 border-b border-border px-4 lg:px-6">
          <span className="lg:hidden"><Mark size={28} /></span>
          <h1 className="text-[15px] font-semibold tracking-tight">{title}</h1>
          <span className="inline-flex items-center gap-1.5 rounded-full border border-border bg-card/60 px-2 py-0.5 text-[10px] font-medium text-muted-foreground"><span className="relative flex h-1.5 w-1.5"><span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-[#4CC38A] opacity-70" /><span className="relative inline-flex h-1.5 w-1.5 rounded-full bg-[#4CC38A]" /></span>Live</span>
          <button aria-label="Sign out" onClick={out} className="ml-auto rounded-md p-2 text-muted-foreground hover:bg-muted lg:hidden"><LogOut className="h-4 w-4" /></button>
        </header>
        <main className="min-h-0 flex-1 overflow-y-auto pb-[84px] lg:pb-0">{children}</main>
        <nav className="fixed inset-x-0 bottom-0 z-40 flex border-t border-border bg-background/80 px-2 pb-[max(env(safe-area-inset-bottom),6px)] pt-1.5 backdrop-blur-xl lg:hidden">
          {items.map((it) => (
            <button key={it.id} onClick={() => app.navigate(it.to)} className={"relative flex flex-1 flex-col items-center gap-0.5 py-1.5 text-[10px] font-medium " + (view === it.id ? "text-primary" : "text-muted-foreground")}>
              {view === it.id && <motion.span layoutId="tab-dot" transition={SPRING} className="absolute -top-1.5 h-0.5 w-8 rounded-full bg-primary" />}
              <it.Icon className="h-5 w-5" />{it.label}
            </button>
          ))}
        </nav>
      </div>
    </div>
  );
}

/* page */
export default function KanboWork({ app, view }: Props) {
  const reduce = !!useReducedMotion();
  if (!app) return <div className="p-6 text-sm text-muted-foreground">Loading…</div>;
  return <WorkInner app={app} view={view === "projects" ? "projects" : "work"} reduce={reduce} />;
}

function WorkInner({ app, view, reduce }: { app: AppHandle; view: string; reduce: boolean }) {
  const cardsRaw = app.rows("card") as R[];
  const projects = app.rows("project") as R[];
  const members = app.rows("member") as R[];
  const itemsAll = app.rows("checklist_item") as R[];
  const isMgr = app.user.role === "manager";
  const mineId = app.me("member") || "";
  const [today, setToday] = useState("");
  const [hour, setHour] = useState(9);
  const [open, setOpen] = useState("");
  const [toast, setToast] = useState<{ id: number; text: string; err: boolean } | null>(null);
  const tid = useRef(0);
  useEffect(() => {
    const d = new Date();
    setToday(d.getFullYear() + "-" + String(d.getMonth() + 1).padStart(2, "0") + "-" + String(d.getDate()).padStart(2, "0"));
    setHour(d.getHours());
  }, []);
  useEffect(() => {
    const offs = ["card", "checklist_item", "project", "member"].map((e) => app.live(e));
    return () => offs.forEach((o) => o());
  }, []);
  const say = (text: string, err = false) => { const id = ++tid.current; setToast({ id, text, err }); setTimeout(() => setToast((t) => (t && t.id === id ? null : t)), 3400); };

  const pById = useMemo(() => { const m: Record<string, R> = {}; projects.forEach((p) => (m[s(p.id)] = p)); return m; }, [projects]);
  const mById = useMemo(() => { const m: Record<string, R> = {}; members.forEach((p) => (m[s(p.id)] = p)); return m; }, [members]);
  const itemsBy = useMemo(() => { const m: Record<string, R[]> = {}; itemsAll.forEach((x) => { (m[s(x.card)] = m[s(x.card)] || []).push(x); }); return m; }, [itemsAll]);
  const late = (c: R) => !!today && !!s(c.due) && s(c.due).slice(0, 10) < today && s(c.stage) !== "done";

  const move = async (c: R, st: string) => {
    if (s(c.stage) === st) return;
    const top = cardsRaw.filter((x) => s(x.stage) === st).reduce((m, x) => Math.max(m, n(x.position)), 0) + 1000;
    try { await app.update("card", s(c.id), { stage: st, position: top }); say("Moved to " + ST_LABEL[st]); } catch (e) { say(msg(e), true); }
  };
  const toggleItem = async (it: R) => { try { await app.update("checklist_item", s(it.id), { done: !it.done }); } catch (e) { say(msg(e), true); } };

  const greeting = hour < 12 ? "Good morning" : hour < 18 ? "Good afternoon" : "Good evening";
  const first = s(app.user.name).split(" ")[0] || "there";
  const toastEl = (
    <div className="pointer-events-none fixed inset-x-0 bottom-24 z-[60] flex justify-center lg:bottom-6">
      <AnimatePresence>
        {toast && (
          <motion.div key={toast.id} initial={{ opacity: 0, y: 16, scale: 0.96 }} animate={{ opacity: 1, y: 0, scale: 1 }} exit={{ opacity: 0, y: 8 }} transition={SPRING} className={"pointer-events-auto flex max-w-[92vw] items-center gap-2 rounded-xl border px-3.5 py-2.5 text-[12px] font-medium shadow-[0_16px_40px_-12px_rgba(0,0,0,0.7)] " + (toast.err ? "border-[#FF6B6B]/40 bg-[#2a1215] text-[#FFB4B4]" : "border-border bg-card text-foreground")}>
            {toast.err ? <AlertCircle className="h-4 w-4 shrink-0" /> : <Check className="h-4 w-4 shrink-0 text-[#4CC38A]" />}{toast.text}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );

  if (view === "projects") {
    const nextSt: Record<string, string> = { planning: "active", active: "shipped" };
    const stLabel: Record<string, string> = { planning: "Planning", active: "Active", shipped: "Shipped" };
    const stCol: Record<string, string> = { planning: "#8A8F98", active: "#F2B94B", shipped: "#4CC38A" };
    const total = cardsRaw.length;
    const done = cardsRaw.filter((c) => s(c.stage) === "done").length;
    const overdue = cardsRaw.filter(late).length;
    const kpis = [
      { label: "Active projects", v: projects.filter((p) => s(p.status) === "active").length, Icon: Rocket, tone: "#7C5CFF", suffix: "" },
      { label: "Open cards", v: total - done, Icon: Target, tone: "#5EA2FF", suffix: "" },
      { label: "Completed", v: total ? Math.round((done / total) * 100) : 0, Icon: Trophy, tone: "#4CC38A", suffix: "%" },
      { label: "Overdue", v: overdue, Icon: Flame, tone: "#FF7B7B", suffix: "" },
    ];
    const advance = async (p: R) => {
      const to = nextSt[s(p.status)]; if (!to) return;
      try { await app.transition("project", s(p.id), "status", to); say(s(p.name) + " is now " + stLabel[to]); } catch (e) { say(msg(e), true); }
    };
    return (
      <Shell app={app} view="projects" title="Projects">
        <div className="mx-auto max-w-[1180px] px-4 pb-10 pt-5 lg:px-8 lg:pt-8">
          <motion.div initial={reduce ? false : { opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }}>
            <div className="text-[11px] font-semibold uppercase tracking-[0.14em] text-primary">Portfolio</div>
            <h2 className="mt-1 text-[26px] font-semibold tracking-tight lg:text-[32px]">Where every project stands</h2>
          </motion.div>
          <div className="mt-5 grid grid-cols-2 gap-3 lg:grid-cols-4">
            {kpis.map((k, i) => (
