const today = ctx.now().toISOString().slice(0, 10);
const cards = await ctx.db.list('card');
let flagged = 0;
for (const c of cards) {
  const late = !!c.due && String(c.due).slice(0, 10) < today && String(c.stage) !== 'done';
  if (late && !c.overdue) { await ctx.db.update('card', String(c.id), { overdue: true }); flagged++; }
  if (!late && c.overdue) { await ctx.db.update('card', String(c.id), { overdue: false }); }
}
ctx.notify({ title: 'Overdue sweep: ' + flagged + ' newly flagged', body: 'Open the board to see cards past their due date.', role: 'manager' });
ctx.log('flagged ' + flagged);
